INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT159-S3-Q23$batch02$, 159, 3, 23, $batch02$Flaw$batch02$, $batch02$Principal: All of our school’s rural students participate in the school’s lunch program because they live too far away to go home for lunch, while roughly one half of their urban counterparts also take part in the program. Some participants in this program, including some of the school’s strongest academic achievers, also participate in extracurricular activities such as sports and drama. Therefore, we know that some of the participants in extracurricular activities are rural students and some are urban students.$batch02$, $batch02$The reasoning in the principal’s argument is flawed because this argument$batch02$, $batch02$C$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$takes for granted that a greater number of strong academic achievers than those who are not strong academic achievers participate in extracurricular activities$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$takes for granted that a greater number of rural students than urban students participate in extracurricular activities$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$ignores the possibility that those who participate both in the lunch program and in extracurricular activities do not include both urban and rural students$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$ignores the possibility that both rural and urban students have many other ways of occupying their time besides extracurricular activities$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$at first uses the word “participate” in one sense and then illicitly allows the word’s meaning to change$batch02$, $batch02$Not Equivocation$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Some extracurricular participants are rural and some are urban.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$The lunch program includes all rural students and about half of urban students. *Some* lunch participants do extracurriculars.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$"Some" can be very few. Picture 100 lunch participants: 60 rural, 40 urban. Ten of them do extracurriculars. Could all ten be rural? Yes. Could all ten be urban? Yes. The lunch program has both kinds of students, but the slice that does extracurriculars might come from only one kind.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the possibility that the overlap is all rural or all urban.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$How many strong achievers versus others do extracurriculars has no bearing on whether both rural and urban students are among them.$batch02$), ($batch02$B$batch02$, $batch02$The principal claims only that *some* of each group participate, not that one group outnumbers the other.$batch02$), ($batch02$C$batch02$, $batch02$The students who do both lunch and extracurriculars might all be rural, or all urban. The mix in the lunch program says nothing about the mix in that overlap, so the principal cannot conclude both groups are represented.$batch02$), ($batch02$D$batch02$, $batch02$Other ways of spending time do not affect whether some rural and some urban students do extracurriculars.$batch02$), ($batch02$E$batch02$, $batch02$"Participate" means taking part in both uses. The meaning does not shift.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT159-S3-Q23$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
